local computer=require("computer"); local filesystem=require("filesystem"); local config=require("config.config"); local M={last=-1e9,data={},permissions={}}; local path=config.dataDir.."/playersData.txt"; if not filesystem.exists(config.dataDir)then filesystem.makeDirectory(config.dataDir)end
local function save()local f=io.open(path,"w");if not f then return false end;for _,p in ipairs(M.data)do f:write(string.format("%s|%s|%s|%s\n",p.name,p.greeting,p.farewell,tostring(p.online)))end;f:close();return true end
function M.load()M.data={};local f=io.open(path,"r");if f then for line in f:lines()do local n,g,b,s=line:match("([^|]+)|([^|]+)|([^|]+)|([^|]+)");if n then M.data[#M.data+1]={name=n,greeting=g,farewell=b,online=s=="true"}end end;f:close()end;if #M.data==0 then M.data={{name="Stawlie_",greeting="Царь батюшка на сервере",farewell="Покинул коноху",online=false}};save()end;M.permissions={};for _,p in ipairs(M.data)do M.permissions[p.name]=true end;if config.debugUser then M.permissions[config.debugUser]=true end end
function M.allowed(n)return M.permissions[n]==true end
function M.add(n,g,b)for _,p in ipairs(M.data)do if p.name==n then return false,"Игрок уже существует"end end;M.data[#M.data+1]={name=n,greeting=g or "Зашёл не в ту дверь",farewell=b or "Покинул сервер",online=false};M.permissions[n]=true;save();return true,"Игрок добавлен"end
function M.remove(n)for i,p in ipairs(M.data)do if p.name==n then table.remove(M.data,i);M.permissions[n]=nil;save();return true,"Игрок удалён"end end;return false,"Игрок не найден"end
function M.setGreeting(n,t)for _,p in ipairs(M.data)do if p.name==n then p.greeting=t;save();return true,"Приветствие обновлено"end end;return false,"Игрок не найден"end
function M.setFarewell(n,t)for _,p in ipairs(M.data)do if p.name==n then p.farewell=t;save();return true,"Прощание обновлено"end end;return false,"Игрок не найден"end
function M.update(force)local now=computer.uptime();if not force and now-M.last<config.playerInterval then return nil end;M.last=now;local ch={};for _,p in ipairs(M.data)do pcall(computer.removeUser,p.name);local ok,on=pcall(computer.addUser,p.name);on=ok and on==true;if on~=p.online then ch[#ch+1]={type=on and "joined" or "left",player=p.name,message=on and p.greeting or p.farewell};p.online=on end;pcall(computer.addUser,p.name)end;save();return M.data,ch end
M.load();return M
